// Emits the executable SQL Server script from ../schema.json (generated by build.mjs from model.mjs).
// Run from this folder after build.mjs:  node emit-sql.mjs
// Output: ../submission/DeepSprout-v5-FULL-Database.sql = header + generated DDL + sql/seed.sql + sql/queries.sql
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const schema = JSON.parse(fs.readFileSync(path.join(root, 'schema.json'), 'utf8'));
const T = schema.tables;
const q = (n) => `[${n}]`;
const qt = (full) => full.split('.').map(q).join('.');
const short = (full) => full.split('.')[1];
const errors = [];

const tableNames = new Set(T.map((t) => t.table));
const modules = [...new Set(T.map((t) => t.module))];

// Immutable (insert-only) tables: the application role is denied UPDATE and DELETE.
const INSERT_ONLY = ['ops.AuditEvent', 'iam.ConsentRecord', 'forms.FormVersion', 'activity.PracticeVersion', 'provider.ExperienceRevision', 'institution.InitiativeRevision', 'shield.BrowserUsagePeriod', 'task.SubmissionAttempt'];

const usedCk = new Map();
const ckName = (t, c) => {
  let n = c.name;
  const key = `${t.module}.${n}`;
  if (usedCk.has(key) && usedCk.get(key) !== t.table) n = `${n}_${short(t.table)}`;
  usedCk.set(`${t.module}.${n}`, t.table);
  return n;
};

function colDef(c) {
  let s = `    ${q(c.name)} ${c.type}`;
  if (c.type === 'rowversion') return s + ' NOT NULL';
  if (c.default === 'IDENTITY(1,1)') return s + ' IDENTITY(1,1) NOT NULL';
  s += c.nullable ? ' NULL' : ' NOT NULL';
  if (c.default !== null && c.default !== undefined) s += ` CONSTRAINT [DF_${c.__t}_${c.name}] DEFAULT (${c.default})`;
  return s;
}

let ddl = '';
const out = (s = '') => { ddl += s + '\n'; };

// ── schemas ──
out('-- 2.1 Schemas');
for (const m of modules) out(`IF SCHEMA_ID(N'${m}') IS NULL EXEC(N'CREATE SCHEMA ${q(m)} AUTHORIZATION dbo;');`);
out('GO');
out();

// ── tables (no foreign keys yet) ──
out('-- 2.2 Tables: primary keys, defaults, CHECK constraints, plain UNIQUE constraints. Foreign keys are added in 2.3 so circular references (root <-> revision) are safe.');
let n = 0;
for (const t of T) {
  n++;
  const cols = t.columns.map((c) => ({ ...c, __t: short(t.table) }));
  const lines = cols.map(colDef);
  lines.push(`    CONSTRAINT [PK_${short(t.table)}] PRIMARY KEY CLUSTERED (${t.primaryKey.map(q).join(', ')})`);
  for (const u of t.unique) {
    if (u.filter) continue;
    lines.push(`    CONSTRAINT [UQ_${short(t.table)}_${u.columns.join('_')}] UNIQUE (${u.columns.map(q).join(', ')})`);
  }
  for (const c of t.checks) lines.push(`    CONSTRAINT [${ckName(t, c)}] CHECK (${c.expression})`);
  // ISJSON on JSON text columns
  for (const c of t.columns) {
    if (/Json$/.test(c.name) && c.type.startsWith('nvarchar')) {
      lines.push(`    CONSTRAINT [CK_${short(t.table)}_${c.name}_IsJson] CHECK (${c.nullable ? `${q(c.name)} IS NULL OR ` : ''}ISJSON(${q(c.name)}) = 1)`);
    }
  }
  out(`-- (${n}/${T.length}) ${t.table} — ${t.purpose}`);
  out(`CREATE TABLE ${qt(t.table)} (\n${lines.join(',\n')}\n);`);
  out('GO');
}
out();

// ── foreign keys ──
out('-- 2.3 Foreign keys (single-column; all added after every table exists)');
let fkCount = 0;
const fkCols = new Map();
for (const t of T) {
  for (const f of t.foreignKeys) {
    if (!tableNames.has(f.references)) { errors.push(`FK target missing ${f.references}`); continue; }
    fkCount++;
    out(`ALTER TABLE ${qt(t.table)} ADD CONSTRAINT [FK_${short(t.table)}_${f.column}] FOREIGN KEY (${q(f.column)}) REFERENCES ${qt(f.references)} ([Id]);`);
    if (!fkCols.has(t.table)) fkCols.set(t.table, []);
    fkCols.get(t.table).push(f.column);
  }
}
out('GO');
out();

// ── filtered unique indexes + query indexes ──
out('-- 2.4 Filtered unique indexes ("one live X") and query indexes');
let ixCount = 0;
for (const t of T) {
  const leading = new Set();
  for (const u of t.unique) leading.add(u.columns[0]);
  let k = 0;
  for (const u of t.unique) {
    if (!u.filter) continue;
    k++;
    out(`CREATE UNIQUE NONCLUSTERED INDEX [UX_${short(t.table)}_${u.columns.join('_')}_${k}] ON ${qt(t.table)} (${u.columns.map(q).join(', ')}) WHERE ${u.filter};`);
    ixCount++;
  }
  for (const i of t.indexes) {
    leading.add(i.columns[0]);
    out(`CREATE NONCLUSTERED INDEX [IX_${short(t.table)}_${i.columns.join('_')}] ON ${qt(t.table)} (${i.columns.map(q).join(', ')})${i.filter ? ` WHERE ${i.filter}` : ''};`);
    ixCount++;
  }
  // FK columns that do not already lead an index
  for (const c of fkCols.get(t.table) || []) {
    if (leading.has(c)) continue;
    leading.add(c);
    out(`CREATE NONCLUSTERED INDEX [IX_${short(t.table)}_${c}] ON ${qt(t.table)} (${q(c)});`);
    ixCount++;
  }
}
out('GO');
out();

// ── security: insert-only history ──
out('-- 2.5 Insert-only history. The application role may read and write everything except UPDATE/DELETE on these tables (no triggers).');
out(`IF DATABASE_PRINCIPAL_ID(N'ds_app') IS NULL CREATE ROLE [ds_app];`);
out('GO');
for (const m of modules) out(`GRANT SELECT, INSERT, UPDATE, DELETE ON SCHEMA::${q(m)} TO [ds_app];`);
for (const tn of INSERT_ONLY) {
  if (!tableNames.has(tn)) { errors.push(`INSERT_ONLY table missing ${tn}`); continue; }
  out(`DENY UPDATE, DELETE ON ${qt(tn)} TO [ds_app];`);
}
out(`IF DATABASE_PRINCIPAL_ID(N'ds_app_demo') IS NULL CREATE USER [ds_app_demo] WITHOUT LOGIN;`);
out(`IF IS_ROLEMEMBER(N'ds_app', N'ds_app_demo') <> 1 ALTER ROLE [ds_app] ADD MEMBER [ds_app_demo];`);
out('GO');

if (errors.length) { console.error(errors.join('\n')); process.exit(1); }

const read = (f) => fs.readFileSync(path.join(here, 'sql', f), 'utf8');
const stamp = (s) => s.replaceAll('{{TABLES}}', String(T.length)).replaceAll('{{FKS}}', String(fkCount)).replaceAll('{{SCHEMAS}}', String(modules.length));
const header = stamp(read('header.sql'));
const seed = read('seed.sql');
const queries = read('queries.sql');
const sql = [header, ddl, read('seed-banner.sql'), seed, read('footer.sql'), queries].join('\n');
fs.mkdirSync(path.join(root, 'submission'), { recursive: true });
fs.writeFileSync(path.join(root, 'submission', 'DeepSprout-v5-FULL-Database.sql'), '﻿' + sql.replace(/\r?\n/g, '\r\n'), 'utf8');
console.log(`tables ${T.length}, schemas ${modules.length}, FKs ${fkCount}, extra indexes ${ixCount}, bytes ${sql.length}`);
